build.benchmark_patch:
diff --git a/crates/apxinf-model/examples/qwen35_context_bench.rs b/crates/apxinf-model/examples/qwen35_context_bench.rs
index ee9e9ac7..0bba1b7c 100644
--- a/crates/apxinf-model/examples/qwen35_context_bench.rs
+++ b/crates/apxinf-model/examples/qwen35_context_bench.rs
@@ -328,7 +328,13 @@ fn main() -> Result<(), Box<dyn std::error::Error>> {
         .into());
     }

-    let prompt = exact_tokens(total_context);
+    let prompt = if let Some(path) = benchmark::optional_path(&args, "--input-ids")? {
+        let bytes = std::fs::read(path)?;
+        if bytes.len() != total_context.checked_mul(4).ok_or("input size overflow")? { return Err("input length mismatch".into()); }
+        let ids: Vec<u32> = bytes.chunks_exact(4).map(|b| u32::from_le_bytes(b.try_into().unwrap())).collect();
+        if ids.iter().any(|&id| id as usize >= benchmark::VOCAB_SIZE) { return Err("invalid token".into()); }
+        ids
+    } else { exact_tokens(total_context) };
     let (prefix, chunk) = prompt.split_at(prefix_tokens);
     // Qwen3.6 owns its cuda-new execution context internally. The trait
     // backend is retained only for the generic LLM surface, so the benchmark
diff --git a/crates/apxinf-model/examples/qwen35_mtp_bench.rs b/crates/apxinf-model/examples/qwen35_mtp_bench.rs
index f74d9519..c3ccdc41 100644
--- a/crates/apxinf-model/examples/qwen35_mtp_bench.rs
+++ b/crates/apxinf-model/examples/qwen35_mtp_bench.rs
@@ -583,7 +583,13 @@ fn main() -> Result<(), Box<dyn std::error::Error>> {
         return Err("--repeats must be at least 1".into());
     }

-    let prompt = exact_prompt(prompt_tokens);
+    let prompt = if let Some(path) = benchmark::optional_path(&args, "--input-ids")? {
+        let bytes = std::fs::read(path)?;
+        if bytes.len() != prompt_tokens.checked_mul(4).ok_or("input size overflow")? { return Err("input length mismatch".into()); }
+        let ids: Vec<u32> = bytes.chunks_exact(4).map(|b| u32::from_le_bytes(b.try_into().unwrap())).collect();
+        if ids.iter().any(|&id| id as usize >= benchmark::VOCAB_SIZE) { return Err("invalid token".into()); }
+        ids
+    } else { exact_prompt(prompt_tokens) };
     let capacity = prompt_tokens
         .checked_add(max_new_tokens)
         .and_then(|value| value.checked_add(MTP_LOOKAHEAD))
